import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUSES = ['신청', '승인', '반려'];

@Controller('api/v1')
export class FnSfr01202Controller {
  @Post('/hr-change-requests')
  @HttpCode(200)
  async createHrChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const targetItem = typeof data['targetItem'] === 'string' ? data['targetItem'].trim() : '';
    const afterValue = typeof data['afterValue'] === 'string' ? data['afterValue'].trim() : '';
    const reason = typeof data['reason'] === 'string' ? data['reason'].trim() : '';
    if (!targetItem || !afterValue || !reason || targetItem.length > 100) {
      throw new ApiError(422, 'INVALID_HR_CHANGE_REQUEST', '변경 대상 항목, 변경 후 값, 변경 사유를 모두 입력해 주세요.');
    }
    const rawAttachment = data['attachmentId'];
    let attachmentId: string | null = null;
    if (rawAttachment !== undefined && rawAttachment !== null && rawAttachment !== '') {
      if (!Number.isInteger(Number(rawAttachment))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '증빙 첨부파일 ID가 올바르지 않습니다.');
      }
      attachmentId = String(rawAttachment);
    }
    return transaction(async (db) => {
      if (attachmentId !== null) {
        const found = await db.query(
          'SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)',
          { attachmentId },
        );
        if (found.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '증빙 첨부파일을 찾을 수 없습니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO hr_change_request
           (employee_id, attachment_id, target_item, after_value, reason, status, created_at, updated_at)
         VALUES
           (CAST(:userId AS bigint), CAST(:attachmentId AS bigint), :targetItem, :afterValue, :reason, '신청', now(), now())
         RETURNING hr_change_request_id AS "hrChangeRequestId", status`,
        { userId: user.id, attachmentId, targetItem, afterValue, reason },
      );
      return rows[0];
    });
  }

  @Get('/hr-change-requests')
  async listHrChangeRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '인사 담당자');
    const query = checks.queryOf(req.query);
    const rawPage = query['page'];
    const rawSize = query['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    let size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    size = Math.min(size, MAX_SIZE);
    const rawStatus = query['status'];
    const status = rawStatus === undefined || rawStatus === '' ? null : String(rawStatus);
    if (status !== null && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 상태가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const params = { status, size, offset: page * size };
      const items = await db.query(
        `SELECT hr_change_request_id AS "hrChangeRequestId",
                employee_id AS "employeeId",
                target_item AS "targetItem",
                before_value AS "beforeValue",
                after_value AS "afterValue",
                reason AS "reason",
                status AS "status",
                reviewed_at AS "reviewedAt",
                reject_reason AS "rejectReason"
           FROM hr_change_request
          WHERE (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))
          ORDER BY hr_change_request_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS total
           FROM hr_change_request
          WHERE (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))`,
        { status },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/hr-change-requests/:hrChangeRequestId/approve')
  @HttpCode(200)
  async approveHrChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = req.params['hrChangeRequestId'];
    return transaction(async (db) => {
      if (!/^\d+$/.test(id)) {
        throw new ApiError(404, 'HR_CHANGE_REQUEST_NOT_FOUND', '변경 신청 건을 찾을 수 없습니다.');
      }
      const found = await db.query(
        `SELECT status, before_value AS "beforeValue", after_value AS "afterValue"
           FROM hr_change_request
          WHERE hr_change_request_id = CAST(:id AS bigint)
            FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'HR_CHANGE_REQUEST_NOT_FOUND', '변경 신청 건을 찾을 수 없습니다.');
      }
      if (found[0].status !== '신청') {
        throw new ApiError(409, 'HR_CHANGE_REQUEST_ALREADY_PROCESSED', '이미 처리된 신청 건입니다.');
      }
      const rows = await db.query(
        `UPDATE hr_change_request
            SET status = '승인',
                reviewer_id = CAST(:userId AS bigint),
                reviewed_at = now(),
                updated_at = now()
          WHERE hr_change_request_id = CAST(:id AS bigint)
          RETURNING hr_change_request_id AS "hrChangeRequestId", status, reviewed_at AS "reviewedAt"`,
        { id, userId: user.id },
      );
      await db.execute(
        `INSERT INTO change_history
           (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
         VALUES
           ('hr_change_request', CAST(:id AS bigint), '승인', now(), CAST(:userId AS bigint), :beforeValue, :afterValue, now(), now())`,
        { id, userId: user.id, beforeValue: found[0].beforeValue, afterValue: found[0].afterValue },
      );
      // TODO: 승인 값을 인사정보(hr_record 등)에 반영하는 대상 테이블·컬럼이 schema.sql에 없어 구현하지 못했다.
      return rows[0];
    });
  }

  @Post('/hr-change-requests/:hrChangeRequestId/reject')
  @HttpCode(200)
  async rejectHrChangeRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const id = req.params['hrChangeRequestId'];
    const data = checks.inputOf(req.body);
    const rejectReason = typeof data['rejectReason'] === 'string' ? data['rejectReason'].trim() : '';
    if (!rejectReason) {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    return transaction(async (db) => {
      if (!/^\d+$/.test(id)) {
        throw new ApiError(404, 'HR_CHANGE_REQUEST_NOT_FOUND', '변경 신청 건을 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT status FROM hr_change_request WHERE hr_change_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'HR_CHANGE_REQUEST_NOT_FOUND', '변경 신청 건을 찾을 수 없습니다.');
      }
      if (found[0].status !== '신청') {
        throw new ApiError(409, 'HR_CHANGE_REQUEST_ALREADY_PROCESSED', '이미 처리된 신청 건입니다.');
      }
      const rows = await db.query(
        `UPDATE hr_change_request
            SET status = '반려',
                reject_reason = :rejectReason,
                reviewer_id = CAST(:userId AS bigint),
                reviewed_at = now(),
                updated_at = now()
          WHERE hr_change_request_id = CAST(:id AS bigint)
          RETURNING hr_change_request_id AS "hrChangeRequestId", status, reviewed_at AS "reviewedAt"`,
        { id, userId: user.id, rejectReason },
      );
      return rows[0];
    });
  }
}

