import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, TextInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr01202Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<'' | 'create' | 'detail' | 'reject'>('');
  const [selected, setSelected] = useState<Row | null>(null);
  const [targetItem, setTargetItem] = useState('');
  const [afterValue, setAfterValue] = useState('');
  const [reason, setReason] = useState('');
  const [attachmentId, setAttachmentId] = useState<number | string>('');
  const [rejectReason, setRejectReason] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/hr-change-requests', role, undefined, { status, page, size: PAGE_SIZE }),
    [status, page, role],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/hr-change-requests', role, undefined, { status: '신청', page: 0, size: 5 }),
    [role],
  );

  const isEmployee = role === '임직원';
  const isHr = role === '인사 담당자';

  function refresh() {
    list.reload();
    pending.reload();
  }

  function close() {
    setMode('');
    setSelected(null);
  }

  function openCreate() {
    setTargetItem('');
    setAfterValue('');
    setReason('');
    setAttachmentId('');
    setMode('create');
  }

  function openDetail(row: Row) {
    setSelected(row);
    setMode('detail');
  }

  async function submitCreate() {
    if (!targetItem.trim() || !afterValue.trim() || !reason.trim()) {
      throw new Error('변경 대상 항목, 변경 후 값, 변경 사유를 모두 입력해 주세요.');
    }
    await call('POST', '/hr-change-requests', role, {
      targetItem,
      afterValue,
      reason,
      attachmentId,
    });
    notify('변경을 신청했습니다.');
    close();
    refresh();
  }

  async function approve() {
    if (!selected) return;
    await call('POST', `/hr-change-requests/${selected['hrChangeRequestId']}/approve`, role, {});
    notify('승인했습니다.');
    close();
    refresh();
  }

  async function submitReject() {
    if (!selected) return;
    if (!rejectReason.trim()) {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    await call('POST', `/hr-change-requests/${selected['hrChangeRequestId']}/reject`, role, { rejectReason });
    notify('반려했습니다.');
    close();
    refresh();
  }

  const data = list.data;
  const waiting = pending.data;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles
          items={[
            ['처리 대기', <Num2 key="w" value={waiting ? waiting.total : 0} />],
            ['조회 결과', <Num2 key="t" value={data ? data.total : 0} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>변경 신청</h2>
        <Filters
          onSearch={() => { setPage(0); list.reload(); }}
          onReset={() => { setStatus(''); setPage(0); }}
        >
          <Field label="처리 상태">
            <Select
              value={status}
              onChange={(v) => { setStatus(v); setPage(0); }}
              options={[['신청', '신청'], ['승인', '승인'], ['반려', '반려']]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          {isEmployee && <button type="button" onClick={openCreate}>변경 신청</button>}
        </Band>
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          rows={data ? data.items : []}
          onRowClick={openDetail}
          empty="변경 신청이 없습니다."
          columns={[
            { key: 'employeeId', label: '신청자 임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
            { key: 'targetItem', label: '변경 대상 항목' },
            { key: 'afterValue', label: '변경 후 값' },
            { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
            { key: 'reviewedAt', label: '검토 일시', render: (r) => <DateText value={r['reviewedAt']} time /> },
          ]}
        />
        <Pager page={page} size={PAGE_SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          rows={waiting ? waiting.items : []}
          onRowClick={openDetail}
          empty="대기 중인 신청이 없습니다."
          columns={[
            { key: 'targetItem', label: '변경 대상 항목' },
            { key: 'employeeId', label: '신청자 임직원 ID', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
          ]}
        />
      </section>

      {mode === 'create' && (
        <Drawer title="인사정보 변경 신청" onClose={close}>
          <Form onSubmit={submitCreate} submit="신청">
            <Field label="변경 대상 항목" required>
              <TextInput value={targetItem} onChange={setTargetItem} />
            </Field>
            <Field label="변경 후 값" required>
              <TextInput value={afterValue} onChange={setAfterValue} />
            </Field>
            <Field label="변경 사유" required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            <Field label="증빙 첨부파일 ID">
              <LookupSelect table="attachment" role={role} value={attachmentId} onChange={setAttachmentId} placeholder="선택 안 함" />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'detail' && selected && (
        <Drawer title="변경 신청 상세" onClose={close}>
          <Pairs
            items={[
              ['신청자 임직원 ID', <RefName key="e" table="employee" role={role} value={selected['employeeId']} />],
              ['변경 대상 항목', String(selected['targetItem'] ?? '')],
              ['변경 전 값', String(selected['beforeValue'] ?? '')],
              ['변경 후 값', String(selected['afterValue'] ?? '')],
              ['변경 사유', String(selected['reason'] ?? '')],
              ['처리 상태', <Badge key="s" value={selected['status']} />],
              ['검토 일시', <DateText key="d" value={selected['reviewedAt']} time />],
              ['반려 사유', String(selected['rejectReason'] ?? '')],
            ]}
          />
          {isHr && selected['status'] === '신청' && (
            <Form onSubmit={approve} submit="승인" note="승인하면 변경 이력이 남습니다." />
          )}
          {isHr && selected['status'] === '신청' && (
            <button type="button" onClick={() => { setRejectReason(''); setMode('reject'); }}>반려</button>
          )}
        </Drawer>
      )}

      {mode === 'reject' && selected && (
        <Drawer title="변경 신청 반려" onClose={close}>
          <Form onSubmit={submitReject} submit="반려" danger>
            <Field label="반려 사유" required wide>
              <TextInput value={rejectReason} onChange={setRejectReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}

function Num2({ value }: { value: number }) {
  return <Num value={value} />;
}
